#!/usr/bin/env node
/*
 * Exports the shared synthetic data set as JSON so the Java and Python services can read the same
 * customers and balances the Angular apps render. The generator lives in @meridian/domain-fixtures;
 * this script only serialises it. Regenerated by `make install`; the committed copy is what the
 * demo runs against, so do not change the seed without telling the front end teams (PLAT-3312).
 *
 * Bedrock fixed width records are included pre-encoded so bedrock-adapter's fixture mode and the
 * Java copybook decoders can be cross checked against the TypeScript encoder.
 */
const fs = require('fs');
const path = require('path');
const fixtures = require('../libs/ts/domain-fixtures/dist');

const set = fixtures.generateFixtures({ seed: 'meridian' });

// 18 months of history for 81 accounts is 26 MB of JSON. The services only need the recent
// window (statements-api renders one month at a time, bff-retail pages 50). Keep the newest
// TXNS_PER_ACCOUNT per account; ids stay stable because the generator is seeded.
const TXNS_PER_ACCOUNT = Number(process.env.FIXTURE_TXNS_PER_ACCOUNT || 90);
const perAccount = new Map();
for (const t of set.transactions) {
  const list = perAccount.get(t.accountId) || [];
  list.push(t);
  perAccount.set(t.accountId, list);
}
set.transactions = [...perAccount.values()]
  .flatMap((list) => list.sort((a, b) => b.postedAt.localeCompare(a.postedAt)).slice(0, TXNS_PER_ACCOUNT));
const customersById = new Map(set.customers.map((c) => [c.customerId, c]));

const out = {
  generatedFrom: '@meridian/domain-fixtures',
  seed: set.seed,
  asOf: '2024-11-15T00:00:00.000Z',
  customers: set.customers,
  accounts: set.accounts,
  transactions: set.transactions,
  alertPreferences: set.alertPreferences,
  entitlements: set.entitlements,
  bedrock: {
    accountRecords: set.accounts.map((a) => fixtures.encodeAccountRecord(a, customersById.get(a.customerId))),
    transactionRecords: set.transactions.map((t) => fixtures.encodeTransactionRecord(t))
  }
};

const target = path.join(__dirname, '..', 'fixtures', 'meridian-fixtures.json');
fs.writeFileSync(target, JSON.stringify(out) + '\n');
console.log(`wrote ${target}: ${set.customers.length} customers, ${set.accounts.length} accounts, ${set.transactions.length} transactions`);
